script:
frappe.ui.form.on('Print Master Template', {
    refresh: function(frm) {
        frm.trigger('render_preview');
    },
    render_preview: function(frm) {
        // Solo ejecutamos si el documento ya tiene nombre (ya fue guardado)
        if (frm.doc.name) {
            frappe.call({
                method: "print_master.print_master.doctype.print_master_template.print_master_template.get_template_preview",
                args: {
                    template_name: frm.doc.name
                },
                callback: function(r) {
                    if (r.message) {
                        // Buscamos el contenedor del campo HTML y metemos el código
                        // Reemplaza 'preview' por el nombre REAL de tu campo HTML
                        let container = frm.get_field('preview').$wrapper;
                        container.html(r.message);
                    }
                }
            });
        }
    }
});
